head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCaptionAuto]<br/>GridView 의 caption 요소 텍스트를 자동 생성하고 captionTitle 속성값을 설정합니다.",
    "validation" : [
        "GridView 의 caption 요소 텍스트를 자동 생성하고 captionTitle 속성값을 설정합니다. captionAuto 속성값에 관계없이 caption 텍스트가 자동 생성됩니다.",
        "captionTitle(선택) 파라미터로 captionTitle 속성에 적용될 텍스트를 설정합니다. 생략/빈문자열/null/undefined 이면 기존 captionTitle 속성값이 적용됩니다.",
        "자동 생성 caption 은 '{captionTitle}은(는) {Header 값 조합} 을(를) 나타낸 표.' 포맷으로 설정됩니다.",
        "setCaptionAuto() 메소드로 자동 생성 시에는 accessibility=true 여도 shortcut 안내 문구가 생성되지 않습니다.",
        "setCaptionAuto() 실행 시 Footer Table 의 caption 요소값은 재생성하지 않습니다.",
        "setHeaderValue() 로 Header 값 변경 시 caption 에 반영하려면 setCaptionAuto() 를 다시 실행해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_accessibility : true 이면 렌더 시 caption 에 shortcut 안내 문구가 추가됨(초기 caption 기준)
    //                        단, setCaptionAuto() 메소드는 accessibility=true 여도 shortcut 미포함(@spec2)
    let accessibilityVal = con_accessibility.getValue();

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Property 설정은 createCList 공통 함수 사용
    //  - captionTitle : 초기 captionTitle 속성값 (par 생략 시 이 값이 유지됨을 확인)
    //  - captionAuto=false : captionAuto 무관하게 setCaptionAuto 가 동작함을 확인
    let cList = $c.gcm.createCList({
        captionTitle: "사원 목록",
        captionAuto: "false",
        accessibility: accessibilityVal,
        dataList: "data:dlt_bind",
        checkAllType: "false"
    });

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="accessibility=' + accessibilityVal + ', captionAuto=false, 초기 captionTitle=사원 목록 인 GridView 생성 (Header 4컬럼 사번/이름/부서/직급 + gBody + Footer 1행)"', '', 'label1');

    // target 생성 (Footer Table 포함 - @spec3 확인용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // setCaptionAuto 호출 전 Footer caption 을 미리 설정해 두어, 이후 setCaptionAuto 가 Footer caption 을 재생성하지 않음(@spec3) 을 확인
    target1.setFooterCaption("푸터 캡션 원본");
}



// Body Table 의 caption 요소 텍스트 반환 (없으면 null)
scwin.getBodyCaptionText = function () {
    let bodyTable = document.querySelector("table[id*='target1_body_table']");
    if (!bodyTable) {
        return null;
    }
    let caption = bodyTable.getElementsByTagName("caption")[0];
    return caption ? caption.textContent : null;
}



// Footer Table 의 caption 요소 텍스트 반환 (없으면 null)
scwin.getFooterCaptionText = function () {
    let footTable = document.querySelector("table[id*='target1_foot_table']");
    if (!footTable) {
        return null;
    }
    let caption = footTable.getElementsByTagName("caption")[0];
    return caption ? caption.textContent : null;
}



// 현재 Body / Footer caption 텍스트 확인
scwin.btn_checkCaption_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 Body caption 텍스트] " + (scwin.getBodyCaptionText() === null ? 'null' : "'" + scwin.getBodyCaptionText() + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 Footer caption 텍스트] " + (scwin.getFooterCaptionText() === null ? 'null' : "'" + scwin.getFooterCaptionText() + "'"));
}



// setCaptionAuto(captionTitle) 호출 - par_captionTitle 값 전달
//  - @description : caption 자동 생성 + captionTitle 설정
//  - @spec1 : 자동 caption 포맷 '{captionTitle}은(는) {Header 조합}을(를) 나타낸 표.'
//  - @spec2 : accessibility=true 여도 shortcut 안내 미포함
//  - @spec3 : Footer caption 은 재생성 안 함
scwin.btn_setCaptionAuto_onclick = function () {
    let captionTitle = par_captionTitle.getValue();

    let footerBefore = scwin.getFooterCaptionText();
    target1.setCaptionAuto(captionTitle);

    wf_body_bottom.getObj("scwin").setReturnValue("setCaptionAuto('" + captionTitle + "') 호출 (accessibility=" + con_accessibility.getValue() + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("[Body caption 텍스트] " + (scwin.getBodyCaptionText() === null ? 'null' : "'" + scwin.getBodyCaptionText() + "'"));
    // @spec3 : Footer caption 미재생성 (호출 전후 동일)
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer caption 텍스트 (호출 전/후)] '" + footerBefore + "' / '" + scwin.getFooterCaptionText() + "'");
}



// setCaptionAuto() 호출 - 파라미터 생략 (@param : 생략 시 기존 captionTitle 속성값 적용)
scwin.btn_setCaptionAutoNoArg_onclick = function () {
    target1.setCaptionAuto();

    wf_body_bottom.getObj("scwin").setReturnValue("setCaptionAuto() 호출 (파라미터 생략, accessibility=" + con_accessibility.getValue() + ")");
    // 생략 시 기존 captionTitle 속성값(직전 설정값 또는 초기 '사원 목록')이 적용됨
    wf_body_bottom.getObj("scwin").setReturnValue("[Body caption 텍스트] " + (scwin.getBodyCaptionText() === null ? 'null' : "'" + scwin.getBodyCaptionText() + "'"));
}



// setHeaderValue 로 Header 값 변경 후 caption 반영 확인 (@spec4)
//  - setHeaderValue 직후 : caption 미반영 (이전 헤더 조합 유지)
//  - setCaptionAuto 재실행 후 : 변경된 Header 값이 caption 에 반영
scwin.btn_setHeaderValue_onclick = function () {
    // 첫번째 컬럼(사번) Header 값을 '직원번호' 로 변경
    target1.setHeaderValue(0, "직원번호");

    wf_body_bottom.getObj("scwin").setReturnValue("setHeaderValue(0, '직원번호') 호출 후 (setCaptionAuto 미실행)");
    wf_body_bottom.getObj("scwin").setReturnValue("[Body caption 텍스트 - 변경 미반영] " + (scwin.getBodyCaptionText() === null ? 'null' : "'" + scwin.getBodyCaptionText() + "'"));

    // setCaptionAuto 재실행 -> 변경된 Header 반영
    target1.setCaptionAuto();
    wf_body_bottom.getObj("scwin").setReturnValue("setCaptionAuto() 재실행 후");
    wf_body_bottom.getObj("scwin").setReturnValue("[Body caption 텍스트 - 변경 반영] " + (scwin.getBodyCaptionText() === null ? 'null' : "'" + scwin.getBodyCaptionText() + "'"));
}
